package dev.cinematic.p0.metrics

import android.content.ContentValues
import android.net.Uri
import android.os.Build
import android.provider.MediaStore
import androidx.test.platform.app.InstrumentationRegistry
import dev.cinematic.p0.rawcapture.*
import dev.cinematic.p0.testing.writeSyntheticTrialDng
import org.junit.Assert.*
import org.junit.Test
import java.io.File
import java.util.UUID
import java.util.concurrent.TimeUnit

/** Synthetic emulator only, real ordinary backend/authority/journals/MediaStore publisher.
 * Six independent requests with identical generated bytes. All outcomes and bytes must match.
 * 0/50/100 then reversed: small matched comparison, not a Pixel prediction. */
class SaveAuthorityIntervalAndroidTest {
    @Test fun compareZeroFiftyAndHundredMilliseconds() {
        val instrumentation = InstrumentationRegistry.getInstrumentation()
        val args = InstrumentationRegistry.getArguments()
        check(Build.HARDWARE in setOf("ranchu", "goldfish"))
        check(args.getString("isolated") == "true" && args.getString("authorityInterval") == "true")
        val app = instrumentation.targetContext.applicationContext
        check(app.packageName == "dev.cinematic.p0")
        val output = File(app.getExternalFilesDir(null), "authority-interval")
        check(!output.exists() && output.mkdirs())
        val allowed = AutoDevelopConditions(true, false, false, false, true, true, true, true, previewMemoryAvailable = true)
        val fingerprints = mutableListOf<OriginalFingerprint>()
        val jpegHashes = mutableListOf<OriginalFingerprint>()
        val wall = mutableListOf<Long>()
        for ((index, millis) in listOf(0L, 50L, 100L, 100L, 50L, 0L).withIndex()) {
            val label = "run${index}_${millis}ms"
            SaveAuthorityIntervalExperiment.configureForTest(millis)
            val resolver = app.contentResolver
            val original = requireNotNull(resolver.insert(MediaStore.Images.Media.getContentUri(MediaStore.VOLUME_EXTERNAL_PRIMARY),
                ContentValues().apply {
                    put(MediaStore.MediaColumns.DISPLAY_NAME, "synthetic_authority_${UUID.randomUUID()}.dng")
                    put(MediaStore.MediaColumns.MIME_TYPE, "image/x-adobe-dng")
                    put(MediaStore.MediaColumns.RELATIVE_PATH, "Pictures/Cinematic Camera Synthetic Tests/")
                    put(MediaStore.MediaColumns.IS_PENDING, 1)
                }))
            val bytes = requireNotNull(resolver.openOutputStream(original, "w")).use { writeSyntheticTrialDng(it, 4000, 3000, 1) }
            check(resolver.update(original, ContentValues().apply { put(MediaStore.MediaColumns.IS_PENDING, 0) }, null, null) == 1)
            val fingerprint = DngContentVerifier.identify(bytes, { requireNotNull(resolver.openInputStream(original)) })
            fingerprints += fingerprint
            val source = SharedOriginalReference(original.toString(), fingerprint, OriginalGrant.APP_OWNED)
            DevelopExecution.updateConditions(allowed)
            val save = AndroidManualOriginalTrialSaves.prepare(app, source, .45, allowed).get(180, TimeUnit.SECONDS)
            val before = timingStore(app).snapshot().toString(Charsets.US_ASCII).lines()
                .filter { SaveTimingRecord.valid(it) }.map { it.split('\t')[1] }.toSet()
            val start = System.nanoTime()
            val result = save.advance(allowed) { false }.get(1200, TimeUnit.SECONDS)
            val stats = requireNotNull(SaveAuthorityIntervalExperiment.lastStats)
            SaveAuthorityIntervalExperiment.configureForTest(null)
            wall += System.nanoTime() - start
            assertEquals(ManualOriginalTrialSavePhase.PUBLISHED, result.phase)
            assertFalse(save.hasUnreleasedResources)
            assertEquals(fingerprint, DngContentVerifier.verify(fingerprint, { requireNotNull(resolver.openInputStream(original)) }))
            val jpeg = Uri.parse(requireNotNull(result.uri))
            val jpegFingerprint = DngContentVerifier.identifyBounded(JpegOutputDescription.MAX_JPEG_BYTES,
                { requireNotNull(resolver.openInputStream(jpeg)) })
            jpegHashes += jpegFingerprint
            val records = timingStore(app).snapshot().toString(Charsets.US_ASCII).lines().filter { SaveTimingRecord.valid(it) }
                .map { it.split('\t') }.filter { it[1] !in before }
            assertEquals(1, records.map { it[1] }.distinct().size)
            File(output, "$label-stages.tsv").writeText("stage\toutcome\tpixels\tnanos\n" +
                records.joinToString("\n", postfix = "\n") { it.drop(4).joinToString("\t") })
            File(output, "$label-counts.tsv").writeText("calls\thits\tdurable\tforced\tmaxWaitNanos\tmaxCheckNanos\tmaxReusedAgeNanos\n${stats.calls}\t${stats.hits}\t${stats.durable}\t${stats.forced}\t${stats.maxWaitNanos}\t${stats.maxCheckNanos}\t${stats.maxReusedAgeNanos}\n")
            File(output, "$label-summary.txt").writeText("pixels=12000000\nsourceBytes=${fingerprint.bytes}\nsourceSha256=${fingerprint.sha256}\njpegBytes=${jpegFingerprint.bytes}\njpegSha256=${jpegFingerprint.sha256}\nwallNanos=${wall.last()}\npublished=true\nresourcesClosed=true\nsourceUnchanged=true\n")
            // Only exact test-created synthetic media after the successful save and observations.
            check(resolver.delete(jpeg, null, null) == 1)
            check(resolver.delete(original, null, null) == 1)
        }
        assertEquals(1, fingerprints.distinct().size)
        assertEquals("All six JPEG byte hashes must match", 1, jpegHashes.distinct().size)
        File(output, "comparison.txt").writeText("sameInput=true\nsameJpeg=true\norder=0,50,100,100,50,0\n")
        assertFalse(Thread.getAllStackTraces().keys.any { it.isAlive && it.name == "gpu-export-band-reader" })
    }
}
